mutations.before:
if (replanned.digest !== flags.expect) {
  io.stderr(
    `--expect ${flags.expect} does not match the re-planned digest ${replanned.digest}`,
  );
  return 1;
}

mutations.after:
if (replanned.digest !== flags.expect) {
  io.stderr(
    `--expect ${flags.expect} does not match the re-planned digest ${replanned.digest}`,
  );
}

mutations.before:
if (objectStore() !== "s3") {
  return `apply needs OBJECT_STORE=s3, and OBJECT_STORE is ${objectStore()}`;
}

if (existsSync(flags.result!)) {
  io.stderr(await describeResultRefusal(flags.result!));
  return 1;
}
handle = await openResult(flags.result!);

try {
  result = (await step(ctx, campaign)) as CampaignResult;
} catch (error) {
  // A thrown step becomes this campaign's entry, not a run abort (N8b2):
  // refused, the error named, partial (a throw proves nothing kept), empty
  // minted; the loop then continues with the next campaign.
  result = {
    outcome: "refused",
    reason: errorMessage(error),
    partial: true,
    minted: { assets: [] },
    unreferencedInputs: { count: 0, names: [] },
  };
}

try {
  await dir.sync();
} finally {
  await dir.close();
}
